// ============================================================
// Helper: get a trivia question for a country (random pick)
// Returns null if no trivia available
// ============================================================
// A trivia question about a guessed country. Skips the ones that give themselves away
// ("…Atacama Desert is in which country?" when the card already says "About your guess:
// Chile"; an answer spelled out in the question), keeps one question per answer (some
// countries have the same fact asked twice), prefers questions this device hasn't seen,
// and only falls back to "What is the capital of…?" when nothing else is left.
const TRIVIA_SEEN_KEY = 'pancake_trivia_seen';
const _triviaNorm = s => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/^the\s+/, '').trim();

function triviaUsable(countryName) {
  const out = [], answers = new Set();
  const c = _triviaNorm(countryName);
  for (const q of TRIVIA[countryName] || []) {
    const a = _triviaNorm(q.a), qq = _triviaNorm(q.q);
    if (a === c || a.includes(c)) continue;                                   // the answer is the guessed country
    if (a.length >= 4 && !/^(true|false|yes|no)$/.test(a) && qq.includes(a)) continue;   // spelled out in the question
    if (answers.has(a)) continue;                                             // the same fact asked twice
    answers.add(a);
    out.push(q);
  }
  return out;
}

function getTriviaQuestion(countryName) {
  const list = triviaUsable(countryName);
  if (!list.length) return null;
  let seen = [];
  try { seen = JSON.parse(localStorage.getItem(TRIVIA_SEEN_KEY)) || []; } catch {}
  const isCapital = q => /\bcapital of\b/i.test(q.q);
  const fresh = list.filter(q => !seen.includes(q.q));
  const pool = (fresh.length ? fresh : list);
  const interesting = pool.filter(q => !isCapital(q));
  const pickFrom = interesting.length ? interesting : pool;
  // All seen already: the one seen longest ago
  const q = fresh.length ? pickFrom[Math.floor(Math.random() * pickFrom.length)]
                         : pickFrom.reduce((best, x) => seen.indexOf(x.q) < seen.indexOf(best.q) ? x : best);
  seen = seen.filter(x => x !== q.q).concat(q.q).slice(-400);
  try { localStorage.setItem(TRIVIA_SEEN_KEY, JSON.stringify(seen)); } catch {}
  return { ...q, fresh: fresh.length > 0 };   // fresh: this device hadn't seen it (for analytics)
}

// ============================================================
// Helper: compass direction from one lat/lon to another
// Returns one of: N, NE, E, SE, S, SW, W, NW
//
// Map direction (a rhumb line: the steady heading you'd follow on a flat
// world map), going the shorter way east or west. The great-circle start
// bearing was used before, but over long distances it curves over the poles
// (USA → India starts out heading north), which reads as wrong to players.
// ============================================================
function compassBearing(fromLat, fromLon, toLat, toLon) {
  let dLon = toLon - fromLon;
  if (dLon > 180) dLon -= 360;
  if (dLon < -180) dLon += 360;
  const clampLat = l => Math.max(-89.5, Math.min(89.5, l));
  const mercY = l => Math.log(Math.tan(Math.PI / 4 + toRad(clampLat(l)) / 2));
  const dPsi = mercY(toLat) - mercY(fromLat);
  const bearing = (toDeg(Math.atan2(toRad(dLon), dPsi)) + 360) % 360;
  const dirs = ['N','NE','E','SE','S','SW','W','NW'];
  return dirs[Math.round(bearing / 45) % 8];
}

const COMPASS_ARROW = { N:'⬆️', NE:'↗️', E:'➡️', SE:'↘️', S:'⬇️', SW:'↙️', W:'⬅️', NW:'↖️' };

